"""Cart pricing."""

import re

from cart.models import Line, Totals

_COUPON = re.compile(r"(PERCENT|FIXED):([0-9]+)")


def _percent_of(cents: int, percent: int) -> int:
    """`percent` percent of `cents`, rounded to a whole cent with halves up."""
    return (cents * percent + 50) // 100


def _parse_coupon(coupon: str) -> tuple[str, int]:
    match = _COUPON.fullmatch(coupon)
    if match is None:
        raise ValueError(f"invalid coupon: {coupon!r}")
    kind, value = match.group(1), int(match.group(2))
    if kind == "PERCENT" and not 1 <= value <= 100:
        raise ValueError(f"percentage out of range: {value}")
    return kind, value


def price_cart(lines: list[Line], coupon: str | None = None) -> Totals:
    """Price a cart. See README.md for the discount rules."""
    for line in lines:
        if line.qty < 1:
            raise ValueError(f"invalid quantity for {line.sku!r}: {line.qty}")
        if line.unit_cents < 0:
            raise ValueError(f"invalid unit price for {line.sku!r}: {line.unit_cents}")
    parsed = _parse_coupon(coupon) if coupon is not None else None

    subtotal = 0
    bulk_discount = 0
    for line in lines:
        amount = line.unit_cents * line.qty
        subtotal += amount
        if line.qty >= 10:
            bulk_discount += _percent_of(amount, 10)

    remaining = subtotal - bulk_discount
    coupon_discount = 0
    if parsed is not None:
        kind, value = parsed
        coupon_discount = _percent_of(remaining, value) if kind == "PERCENT" else value
        coupon_discount = min(coupon_discount, remaining)

    discount = bulk_discount + coupon_discount
    return Totals(subtotal, discount, subtotal - discount)
